package com.flowdesk.alert.event;

import org.apache.rocketmq.acl.common.AclClientRPCHook;import org.apache.rocketmq.acl.common.SessionCredentials;import org.apache.rocketmq.client.consumer.DefaultMQPushConsumer;import org.apache.rocketmq.client.consumer.listener.ConsumeConcurrentlyContext;import org.apache.rocketmq.client.consumer.listener.ConsumeConcurrentlyStatus;import org.apache.rocketmq.client.consumer.listener.MessageListenerConcurrently;import org.apache.rocketmq.common.consumer.ConsumeFromWhere;import org.apache.rocketmq.common.message.MessageExt;import org.apache.rocketmq.remoting.protocol.heartbeat.MessageModel;import org.springframework.context.SmartLifecycle;
import org.slf4j.Logger;import org.slf4j.LoggerFactory;
import java.util.ArrayList;import java.util.List;import java.util.Map;import java.util.UUID;import java.util.concurrent.atomic.AtomicBoolean;import java.util.function.Function;

final class TicketResultRocketMqConsumers implements SmartLifecycle{private static final Logger LOG=LoggerFactory.getLogger(TicketResultRocketMqConsumers.class);private final TicketResultProperties properties;private final TicketResultConsumer main;private final TicketResultDlqAcceptor dlq;private final List<DefaultMQPushConsumer> consumers=new ArrayList<>();private final AtomicBoolean running=new AtomicBoolean();TicketResultRocketMqConsumers(TicketResultProperties p,TicketResultConsumer m,TicketResultDlqAcceptor d){properties=p;main=m;dlq=d;}
    public synchronized void start(){if(running.get())return;properties.validate();var hook=new AclClientRPCHook(new SessionCredentials(properties.getAccessKey(),properties.getSecretKey()));try{consumers.add(create(true,hook,dlq::accept));consumers.add(create(false,hook,main::consume));for(var c:consumers)c.start();running.set(true);LOG.info("Ticket result main consumer and DLQ acceptor are ready");}catch(Exception e){consumers.forEach(DefaultMQPushConsumer::shutdown);consumers.clear();throw new IllegalStateException("Alert Ticket result consumers failed closed",e);}}
    private DefaultMQPushConsumer create(boolean acceptor,AclClientRPCHook hook,Function<TicketResultTransportMessage,TicketResultConsumer.Result> handler)throws Exception{var b=AlertEventContract.TICKET_ESTABLISHED;String group=acceptor?b.dlqAcceptorGroup():b.consumerGroup(),topic=acceptor?b.dlqTopic():b.topic();var c=new DefaultMQPushConsumer(group,hook);c.setNamesrvAddr(properties.getNameServer().trim());c.setInstanceName("flowdesk-alert-ticket-result-"+(acceptor?"dlq-":"main-")+UUID.randomUUID());c.setVipChannelEnabled(false);c.setConsumeFromWhere(ConsumeFromWhere.CONSUME_FROM_FIRST_OFFSET);c.setMessageModel(MessageModel.CLUSTERING);c.setConsumeThreadMin(1);c.setConsumeThreadMax(1);c.setPullBatchSize(1);c.setConsumeMessageBatchMaxSize(1);c.setMaxReconsumeTimes(acceptor?AlertEventContract.DLQ_ACCEPTOR_MAX_RECONSUME_TIMES:AlertEventContract.MAX_RECONSUME_TIMES);c.subscribe(topic,"*");c.registerMessageListener((MessageListenerConcurrently)(messages,context)->handle(group,acceptor,handler,messages,context));return c;}
    private static ConsumeConcurrentlyStatus handle(String group,boolean acceptor,Function<TicketResultTransportMessage,TicketResultConsumer.Result> handler,List<MessageExt> messages,ConsumeConcurrentlyContext context){if(messages==null||messages.size()!=1)return retry(acceptor,context);try{var b=AlertEventContract.TICKET_ESTABLISHED;MessageExt m=messages.get(0);String topic=m.getTopic();if(acceptor&&context!=null&&context.getMessageQueue()!=null&&b.acceptorRetryTopic().equals(context.getMessageQueue().getTopic()))topic=b.dlqTopic();var result=handler.apply(new TicketResultTransportMessage(topic,group,m.getKeys(),m.getTags(),m.getBody(),m.getProperties()==null?Map.of():m.getProperties()));return result==TicketResultConsumer.Result.ACK?ConsumeConcurrentlyStatus.CONSUME_SUCCESS:retry(acceptor,context);}catch(RuntimeException e){return retry(acceptor,context);}}
    private static ConsumeConcurrentlyStatus retry(boolean acceptor,ConsumeConcurrentlyContext c){if(acceptor&&c!=null)c.setDelayLevelWhenNextConsume(AlertEventContract.DLQ_ACCEPTOR_RETRY_DELAY_LEVEL);return ConsumeConcurrentlyStatus.RECONSUME_LATER;}public synchronized void stop(){running.set(false);consumers.forEach(DefaultMQPushConsumer::shutdown);consumers.clear();}public boolean isRunning(){return running.get();}public int getPhase(){return Integer.MIN_VALUE+100;}}
